@import '~basic-styles.scss';

.configurationSelector {
  display: flex;
  align-items: center;
  margin-bottom: 10px;
}

.datasetSelector,
.alignmentSelector {
  margin-left: 5px;
  width: 350px;
}

.configCollapseExpand {
  color: $brand-primary;
  cursor: pointer;
  margin-right: $padding-base-horizontal;
}

.holder > span {
  float: right;
}

.viewHolder {
  float: right;
}

.configExpand {
  compose: configCollapseExpand;
  @include icon(caret-up);
  transform: rotate(90deg);
}

.configCollapse {
  compose: configCollapseExpand;
  @include icon(caret-down);
}
